import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Gamepad2, ArrowLeft, User, Mail, Lock } from "lucide-react"; // Import icons
import "./App.css";

export default function Signup({ onSuccess }) {
  const navigate = useNavigate();

  // 1. STATE VARIABLES TO CAPTURE INPUTS
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleSignup = async (e) => {
    e.preventDefault();
    try {
        // 2. SEND DATA TO BACKEND
        const response = await fetch("http://localhost:4000/api/auth/signup", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            // We MUST send 'name', 'email', and 'password'
            body: JSON.stringify({ name, email, password }) 
        });

        const data = await response.json();

        if (response.ok) {
            alert("Account Created Successfully! Please Login.");
            navigate("/login"); // Redirect to Login page
        } else {
            alert(data.message || "Signup failed");
        }
    } catch (error) {
        console.error("Error:", error);
        alert("Server error. Is the backend running?");
    }
  };

  return (
    <div className="auth-container">
      {/* Left Side: Graphic */}
      <div className="auth-left teal-theme">
        <div className="auth-brand">
          <Gamepad2 size={32} /> VidyaQuest
        </div>
        <div className="auth-left-content">
          <h1 className="auth-title">Join the <br/> Quest Today!</h1>
          <p className="auth-desc">Create an account to start your journey, earn badges, and master STEM subjects.</p>
        </div>
      </div>

      {/* Right Side: Signup Form */}
      <div className="auth-right">
        <div style={{ width: '100%', maxWidth: '400px', marginBottom: '1rem' }}>
           <div className="back-link" onClick={() => navigate("/")}>
             <ArrowLeft size={16} /> Back to Home
           </div>
        </div>

        <div className="auth-form-box">
          <h2 style={{marginBottom:'0.5rem'}}>Create Account</h2>
          <p className="form-sub" style={{marginBottom:'2rem'}}>It's free and takes 1 minute</p>

          <form onSubmit={handleSignup}>
            {/* NAME INPUT */}
            <label>Full Name</label>
            <div className="input-group">
                <User size={18} className="input-icon" />
                <input 
                  type="text" 
                  placeholder="Rahul Kumar" 
                  className="input-field-icon" 
                  required 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
            </div>

            {/* EMAIL INPUT */}
            <label style={{marginTop:'1rem'}}>Email Address</label>
            <div className="input-group">
                <Mail size={18} className="input-icon" />
                <input 
                  type="email" 
                  placeholder="you@school.com" 
                  className="input-field-icon" 
                  required 
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
            </div>

            {/* PASSWORD INPUT */}
            <label style={{marginTop:'1rem'}}>Password</label>
            <div className="input-group">
                <Lock size={18} className="input-icon" />
                <input
                  type="password"
                  placeholder="Minimum 6 characters"
                  className="input-field-icon"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
            </div>

            <button type="submit" className="btn-auth btn-teal" style={{marginTop:'2rem'}}>
              Sign Up
            </button>
          </form>

          <div className="auth-link" style={{marginTop: '1.5rem', textAlign: 'center'}}>
             Already have an account? <span style={{color: '#0d9488', fontWeight: 'bold', cursor: 'pointer'}} onClick={() => navigate('/login')}>Sign In</span>
          </div>
        </div>
      </div>
    </div>
  );
}
